def solve():
    solutions = []
    for a in range(1, 11):
        for b in range(a, 11):
            for c in range(b, 11):
                lhs = a**3 * (b**3 + c**3)
                rhs = 2012 * (a * b * c + 2)
                if lhs == rhs:
                    solutions.append((a, b, c))
    return solutions

solutions = solve()
print("Found solutions:", solutions)

def check_bc_integer(k):
    """Checks if bc is an integer for a given k."""
    numerator = k * (503 * k)**2 - 8
    denominator = 3 * k + 4
    if denominator == 0:
        return False # Should not happen for k>=1

    # Check for divisibility
    if numerator % denominator == 0:
        bc = numerator // denominator
        return bc
    else:
        return None

# Test small values of k
results = {}
for k in range(1, 6):
    bc = check_bc_integer(k)
    results[k] = bc

print(results)

